const listTasks = `-- name: ListTasks :many
SELECT t.id, t.title, t.description, t.status, t.priority, t.task_type, t.due_at, t.remind_at, t.completed_at, t.assignee_id, t.entity_type, t.entity_id, t.created_by, t.created_at, t.updated_at, u.display_name AS assignee_name, count(*) OVER () AS total
FROM tasks t LEFT JOIN users u ON u.id = t.assignee_id
WHERE ($1::text IS NULL
       OR rea_search_doc(t.title, t.description, '', '') @@ websearch_to_tsquery('simple', $1)
       OR t.title ILIKE '%' || $1 || '%')
  AND ($2::text IS NULL OR t.status = $2)
  AND ($3::boolean IS NULL OR NOT $3 OR t.status IN ('open', 'in_progress'))
  AND ($4::uuid IS NULL OR t.assignee_id = $4)
  AND ($5::text IS NULL OR t.entity_type = $5)
  AND ($6::uuid IS NULL OR t.entity_id = $6)
  AND ($7::timestamptz IS NULL OR t.due_at < $7)
  AND ($8::text IS NULL OR t.task_type = $8)
ORDER BY
  CASE WHEN $9::text = 'due' THEN t.due_at END ASC NULLS LAST,
  CASE WHEN $9::text = '-created' THEN t.created_at END DESC,
  t.due_at ASC NULLS LAST, t.created_at DESC, t.id
LIMIT $11 OFFSET $10
`

type ListTasksParams struct {
	Q          *string    `json:"q"`
	Status     *string    `json:"status"`
	OpenOnly   *bool      `json:"open_only"`
	AssigneeID *uuid.UUID `json:"assignee_id"`
	EntityType *string    `json:"entity_type"`
	EntityID   *uuid.UUID `json:"entity_id"`
	DueBefore  *time.Time `json:"due_before"`
	TaskType   *string    `json:"task_type"`
	Sort       string     `json:"sort"`
	Off        int32      `json:"off"`
	Lim        int32      `json:"lim"`
}

type ListTasksRow struct {
	Task         Task    `json:"task"`
	AssigneeName *string `json:"assignee_name"`
	Total        int64   `json:"total"`
}

func (q *Queries) ListTasks(ctx context.Context, arg ListTasksParams) ([]ListTasksRow, error) {
	rows, err := q.db.Query(ctx, listTasks,
		arg.Q,
		arg.Status,
		arg.OpenOnly,
		arg.AssigneeID,
		arg.EntityType,
		arg.EntityID,
		arg.DueBefore,
		arg.TaskType,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTasksRow{}
	for rows.Next() {
		var i ListTasksRow
		if err := rows.Scan(
			&i.Task.ID,
			&i.Task.Title,
			&i.Task.Description,
			&i.Task.Status,
			&i.Task.Priority,
			&i.Task.TaskType,
			&i.Task.DueAt,
			&i.Task.RemindAt,
			&i.Task.CompletedAt,
			&i.Task.AssigneeID,
			&i.Task.EntityType,
			&i.Task.EntityID,
			&i.Task.CreatedBy,
			&i.Task.CreatedAt,
			&i.Task.UpdatedAt,
			&i.AssigneeName,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

